/***
 * MARK: buildChangelogGitFormat
 * @description Builds the `git log --format=` value both the deploy-time baker
 *   (`scripts/generate-changelog.mjs`) and the serve-time live fallback
 *   (`api/deployManager.js`) pass to git, so the emitted fields can never
 *   drift from the order `parseGitLog` reads (`%H` sha, `%h` short, `%an`
 *   author, `%ae` email, `%aI` date, `%s` subject, `%b` body).
 *
 *   The separators are git `%x00`/`%x1e` escapes, never the literal FIELD_SEP
 *   / RECORD_SEP characters: both callers spawn git via an argv array (no
 *   shell, per the `api/git.js` no-shell rule), and an argv string cannot
 *   carry a NUL byte — a literal FIELD_SEP would truncate the `--format`
 *   argument at the first field and bake an empty history. Git decodes the
 *   escapes back to FIELD_SEP / RECORD_SEP in its stdout, which is what
 *   `parseGitLog` splits on.
 * @example buildChangelogGitFormat() => '%H%x00%h%x00%an%x00%ae%x00%aI%x00%s%x00%b%x1e'
 * @returns {string} The `--format=` value (without the `--format=` prefix).
 ***/
export function buildChangelogGitFormat() {
	return ["%H", "%h", "%an", "%ae", "%aI", "%s", "%b"].join("%x00") + "%x1e";
}
===== shared/changelogHistory/changelogLimits.js =====
/***
 * MARK: changelogLimits
 * @description Shared size bounds for the baked Kainbain changelog. Both the
 *   deploy-time baker (`scripts/generate-changelog.mjs`) and the serve-time
 *   live-git fallback (`api/deployManager.js`) read these, so a bound can
 *   never drift between what is baked and what is served live. The separators
 *   are the wire format of the `git log --format` output both sides parse.
 * @example import { DEFAULT_LIMIT } from './changelogLimits.js'
 ***/

/***
 * MARK: DEFAULT_LIMIT
 * @description How many task-merge entries one changelog artifact holds at
 *   most. 200 entries stay fast to bake, small on disk (~140KB with bodies
 *   capped), and quick to render behind the dialog's "Show more" paging.
 * @example DEFAULT_LIMIT => 200
 ***/
export const DEFAULT_LIMIT = 200;

/***
 * MARK: MAX_BODY_CHARS
 * @description Per-entry body cap. KainBain auto-commit messages embed whole
 *   task prompts (averaging ~3KB) — uncapped bodies push 200 entries to
 *   ~675KB, capped they stay near ~140KB. Longer bodies are cut with a
 *   `bodyTruncated` flag so the dialog can offer the full text honestly.
 * @example MAX_BODY_CHARS => 500
 ***/
export const MAX_BODY_CHARS = 500;

/***
 * MARK: FIELD_SEP
 * @description Separates fields inside one `git log` record (NUL). Commit
 *   subjects can hold pipes and quotes, so a printable separator would split
 *   real text — NUL never appears in a commit message (git truncates there).
 * @example ['a', 'b'].join(FIELD_SEP) => 'a\x00b'
 ***/
export const FIELD_SEP = "\x00";

/***
 * MARK: RECORD_SEP
 * @description Separates whole `git log` records (ASCII record separator).
 *   Bodies span lines, so newline cannot delimit records.
 * @example ['r1', 'r2'].join(RECORD_SEP) => 'r1\x1er2'
 ***/
export const RECORD_SEP = "\x1e";
===== shared/changelogHistory/filterChangelogEntries.js =====
import { isAdminCommitSubject } from "./isAdminCommitSubject.js";

/***
 * MARK: filterChangelogEntries
 * @description Drops automation-noise entries (see `isAdminCommitSubject`)
 *   from an already-parsed entry list, keeping newest-first order. Never
 *   throws: a non-list reads as an empty changelog so one malformed source
 *   cannot break the dialog.
 * @example filterChangelogEntries([{ subject: 'KainBain: sync' }]) => []
 * @example filterChangelogEntries([{ subject: 'Fix the queue chip' }]) => [{ subject: 'Fix the queue chip' }]
 * @param {Array<Object>} entries - Parsed changelog entries, newest first.
 * @returns {Array<Object>} The kept entries, newest first.
 ***/
export function filterChangelogEntries(entries) {
	if (!Array.isArray(entries)) return [];
	return entries.filter((entry) => !isAdminCommitSubject(entry?.subject));
}
===== shared/changelogHistory/isAdminCommitSubject.js =====
/***
 * MARK: admin commit patterns
 * @description Why each pattern is automation noise rather than shipped work:
 *   `KainBain:` subjects are engine auto-commits (pending-work snapshots,
 *   converge/merge-latest syncs); `kb/<uuid>` subjects are per-stage runner
 *   output commits; every listed merge shape only syncs branches (task work
 *   lands on the default branch as squash commits with their own subjects,
 *   so dropping the sync merge never hides the work itself). A merge that
 *   carries real review wording (for example `Merge main: keep the
 *   model-reporting fix`) matches none of these and is kept.
 ***/
const KAINBAIN_PREFIX = "KainBain:";
const RUNNER_OUTPUT_SUBJECT = /^kb\/[0-9a-f-]{8,}/i;
const REMOTE_TRACKING_MERGE = /^merge remote-tracking branch\b/i;
const LOCAL_BRANCH_MERGE = /^merge\s+branch\b.*\binto\s+kb\/[0-9a-f-]{8,}/i;
const ORIGIN_MERGE = /^merge\s+origin\//i;
const MERGE_INTO_TASK_BRANCH = /\binto\s+kb\/[0-9a-f-]{8,}/i;

/***
 * MARK: isAdminCommitSubject
 * @description Decides whether a commit subject is automation noise that the
 *   changelog should hide: engine auto-commits, runner stage-output commits,
 *   and branch-sync merges. Anything else — human task work, squash-merge
 *   subjects, real merges with review wording — is kept. Unknown shapes
 *   (non-strings, blank lines) count as noise so a malformed subject can
 *   never slip an unreadable row into the dialog.
 * @example isAdminCommitSubject('KainBain: auto-commit pending work') => true
 * @example isAdminCommitSubject("Merge branch 'main' into kb/2b990c4f-2026") => true
 * @example isAdminCommitSubject('Merge origin/main into kb/2b990c4f-2026') => true
 * @example isAdminCommitSubject("Merge remote-tracking branch 'origin/main' into kb/aa-2026") => true
 * @example isAdminCommitSubject('Merge main: keep the model-reporting fix') => false
 * @example isAdminCommitSubject('Harden runner log transport') => false
 * @param {string} subject - The commit subject line.
 * @returns {boolean} True when the commit is automation noise to hide.
 ***/
export function isAdminCommitSubject(subject) {
	if (typeof subject !== "string") return true;
	const line = subject.trim();
	if (line.length === 0) return true;
	if (line.startsWith(KAINBAIN_PREFIX)) return true;
	if (RUNNER_OUTPUT_SUBJECT.test(line)) return true;
	if (REMOTE_TRACKING_MERGE.test(line)) return true;
	if (LOCAL_BRANCH_MERGE.test(line)) return true;
	if (ORIGIN_MERGE.test(line)) return true;
	if (MERGE_INTO_TASK_BRANCH.test(line)) return true;
	return false;
}
