		const entries = filterChangelogEntries(parseGitLog(raw)).slice(0, DEFAULT_LIMIT);
		const subjects = git(["log", branch, "--format=%s"]).split("\n");
		const totalCount = subjects.filter((subject) => !isAdminCommitSubject(subject)).length;
		const data = {
			generatedAt: new Date().toISOString(), branch,
			commit: git(["rev-parse", branch]).trim(),
			totalCount, truncated: totalCount > entries.length, limit: DEFAULT_LIMIT, entries,
		};
		this.#liveChangelog = { at: now, data };
		return data;
	} catch {
		return null;
	}
}

/***
 * MARK: resolveChangelogBranch
 * @description Picks the history to serve live: local `master` first,
 *   then local `main`, then the `origin/HEAD` symbolic target, then the
 *   remote-tracking `origin/master` / `origin/main` refs directly — the
 *   same order the baker (`scripts/generate-changelog.mjs`) resolves, so
 *   a checkout without a local default branch still serves the history it
 *   has instead of reporting "not-baked". Candidate refs are verified with
 *   `rev-parse --verify` (argv array, no shell) and the symbolic target
 *   is shape-checked before use, so an odd ref reads as null rather than
 *   running an unintended revision.
 * @example manager.resolveChangelogBranch() => 'master'
 * @returns {string|null} The branch to read, or null when none resolves.
 **/
#resolveChangelogBranch() {
	for (const name of ["master", "main"]) {
		const probe = spawnSync("git", ["rev-parse", "--verify", "--quiet", `refs/heads/${name}`], {
			cwd: this.repoRoot,
			encoding: "utf8",
		});
		if (!probe.error && probe.status === 0) return name;
	}
	const head = spawnSync("git", ["symbolic-ref", "refs/remotes/origin/HEAD"], {
		cwd: this.repoRoot,
		encoding: "utf8",
	});
	if (!head.error && head.status === 0) {
		const branch = String(head.stdout || "").replace("refs/remotes/origin/", "").trim();
		if (branch && !branch.startsWith("-") && !branch.includes("..") && !/\s/.test(branch)) {
			const verify = spawnSync("git", ["rev-parse", "--verify", "--quiet", branch], {
				cwd: this.repoRoot,
				encoding: "utf8",
			});
			if (!verify.error && verify.status === 0) return branch;
		}
	}
	for (const name of ["origin/master", "origin/main"]) {
		const probe = spawnSync("git", ["rev-parse", "--verify", "--quiet", `refs/remotes/${name}`], {
			cwd: this.repoRoot,
			encoding: "utf8",
		});
		if (!probe.error && probe.status === 0) return name;
	}
	return null;
}

/***
 * MARK: getStatus
 * @description Returns the current deploy status: whether a deploy is running,
 *   the last result, the live build number, and the rollback history.
 * @example manager.getStatus() => { running: false, build: {...}, lastResult: {...}, history: [...] }
 * @returns {Object}
 ***/
getStatus() {
	return {
		running: this.running,
		pid: this.currentPid,
		build: this.readBuild(),
		lastResult: this.readJson("last-result.json"),
		state: this.readJson("state.json"),
		history: this.readHistory(),
		deployDir: this.deployDir,
	};
}

/***
 * MARK: triggerDeploy
 * @description Spawns `./deploy.sh --prod` (or `--fast`) detached so it survives

=== BuildHashTrigger ===
import React from 'react';
import { useLiveBuild } from './useLiveBuild';
import { InfoTooltip } from '../common/InfoTooltip';
import { ChangelogModal } from './ChangelogModal';

/***
 * MARK: BuildHashTrigger
 * @description Slightly greyed-out monospace `#B<build><·short SHA>` trigger
 *   living in the Now Playing bar's right rail, left of the queue-depth chip.
 *   Clicking (or keyboard-activating) it opens the Kainbain changelog baked
 *   into the live build. Hidden when no build identity is baked (dev and
 *   pre-deploy builds), so it never shows a fabricated hash.
 * @example <BuildHashTrigger />
 ***/
export function BuildHashTrigger() {
  const { buildNumber, commitSha, changelogOpen, setChangelogOpen } = useLiveBuild();

  if (buildNumber == null) return null;

  // The stamped `commit` is sometimes a full 40-char SHA (older bakes) or a
  // version-prefixed tag (`1.0.0-<sha>`): display at most the short 7-char
  // form so a long hash can never crowd the 72px bar at narrow widths. The
  // full value is never needed in the DOM — identity is build number + short.
  // `unknown` / blank stamps (a deploy that could not resolve HEAD) are
  // treated as "no hash" so we never fabricate an identity from garbage.
  const rawSha = typeof commitSha === 'string' && commitSha.trim() !== '' ? commitSha.trim() : null;
  const strippedSha = rawSha
    ? rawSha.includes('-')
      ? rawSha.slice(rawSha.lastIndexOf('-') + 1)
      : rawSha
    : null;
  const sha =
    strippedSha != null && strippedSha !== '' && strippedSha.toLowerCase() !== 'unknown'
      ? strippedSha.slice(0, 7)
      : null;
  const label = sha ? `#B${buildNumber}·${sha}` : `#B${buildNumber}`;
  const accessibleName =
    sha != null
      ? `Build ${buildNumber} (${sha}) of the live deployment — show Kainbain changelog`
      : `Build ${buildNumber} of the live deployment — show Kainbain changelog`;

  return (
    <>
      <InfoTooltip
        title={`Live Production Build #B${buildNumber}`}
        description="Self-deploying production build identifier stamped from atomic counter. Click to view the Kainbain changelog baked into this build."
        behindTheScenes="Reads /status which checks ~/apps/kainbain/build.json; the changelog comes from /deploy/changelog (baked at deploy time)."
        position="top-left"
        className="min-w-0"
      >
        <button
          type="button"
          onClick={() => setChangelogOpen(true)}
          className="px-2 py-1 min-h-[44px] min-w-0 max-w-[36vw] sm:max-w-none rounded-sm text-text-muted hover:text-primary text-xs font-mono select-none border border-transparent hover:border-border-standard flex items-center justify-center cursor-pointer transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-primary"
          aria-label={accessibleName}
          data-testid="build-badge"
        >
          {/* Capped width with ellipsis on phones so a long build number can
              never crowd the idle hint / runner boxes out of the 72px bar;
              the untruncated label stays in the accessible name. */}
          <span className="truncate min-w-0">{label}</span>
        </button>
      </InfoTooltip>
      {changelogOpen && (
        <ChangelogModal buildNumber={buildNumber} onClose={() => setChangelogOpen(false)} />
      )}
    </>
  );
}

